/// Safe, SVD-declared read-and-acknowledge interrupt transactions.
pub mod interrupt_snapshot {

    /// Opaque event image sampled from `WIFI_MAC_INTERRUPT`.`STATUS`.
    #[must_use = "an interrupt snapshot must be inspected and acknowledged"]
    #[derive(Debug)]
    pub struct MacInterruptSnapshot(u32);
    impl MacInterruptSnapshot {
        /// Complete masked event image observed by the status read.
        #[inline]
        pub const fn bits(&self) -> u32 {
            self.0
        }
        /// Whether the sampled register contained no asserted event.
        #[inline]
        pub const fn is_empty(&self) -> bool {
            self.0 == 0
        }
        /// Sampled value of SVD field `BITS_0_4_OPAQUE`.
        #[inline]
        pub const fn bits_0_4_opaque(&self) -> u8 {
            (self.0 & 0x1f) as u8
        }
        /// Sampled value of SVD field `RX_ASSOCIATED_AUXILIARY_5`.
        #[inline]
        pub const fn rx_associated_auxiliary_5(&self) -> bool {
            self.0 & 0x00000020 != 0
        }
        /// Sampled value of SVD field `BIT_6_OPAQUE`.
        #[inline]
        pub const fn bit_6_opaque(&self) -> bool {
            self.0 & 0x00000040 != 0
        }
        /// Sampled value of SVD field `TX_COMPLETE`.
        #[inline]
        pub const fn tx_complete(&self) -> bool {
            self.0 & 0x00000080 != 0
        }
        /// Sampled value of SVD field `BSS_COLOR_COLLISION`.
        #[inline]
        pub const fn bss_color_collision(&self) -> bool {
            self.0 & 0x00000100 != 0
        }
        /// Sampled value of SVD field `BITS_9_10_OPAQUE`.
        #[inline]
        pub const fn bits_9_10_opaque(&self) -> u8 {
            (self.0 >> 9 & 0x3) as u8
        }
        /// Sampled value of SVD field `WATCHDOG`.
        #[inline]
        pub const fn watchdog(&self) -> bool {
            self.0 & 0x00000800 != 0
        }
        /// Sampled value of SVD field `BIT_12_OPAQUE`.
        #[inline]
        pub const fn bit_12_opaque(&self) -> bool {
            self.0 & 0x00001000 != 0
        }
        /// Sampled value of SVD field `BIT_13_OPAQUE`.
        #[inline]
        pub const fn bit_13_opaque(&self) -> bool {
            self.0 & 0x00002000 != 0
        }
        /// Sampled value of SVD field `RX_SUCCESS`.
        #[inline]
        pub const fn rx_success(&self) -> bool {
            self.0 & 0x00004000 != 0
        }
        /// Sampled value of SVD field `STA_BEACON_FILTER`.
        #[inline]
        pub const fn sta_beacon_filter(&self) -> bool {
            self.0 & 0x00008000 != 0
        }
        /// Sampled value of SVD field `BITS_16_18_OPAQUE`.
        #[inline]
        pub const fn bits_16_18_opaque(&self) -> u8 {
            (self.0 >> 16 & 0x7) as u8
        }
        /// Sampled value of SVD field `TX_TIMEOUT`.
        #[inline]
        pub const fn tx_timeout(&self) -> bool {
            self.0 & 0x00080000 != 0
        }
        /// Sampled value of SVD field `BIT_20_OPAQUE`.
        #[inline]
        pub const fn bit_20_opaque(&self) -> bool {
            self.0 & 0x00100000 != 0
        }
        /// Sampled value of SVD field `BIT_21_OPAQUE`.
        #[inline]
        pub const fn bit_21_opaque(&self) -> bool {
            self.0 & 0x00200000 != 0
        }
        /// Sampled value of SVD field `BIT_22_OPAQUE`.
        #[inline]
        pub const fn bit_22_opaque(&self) -> bool {
            self.0 & 0x00400000 != 0
        }
        /// Sampled value of SVD field `BIT_23_OPAQUE`.
        #[inline]
        pub const fn bit_23_opaque(&self) -> bool {
            self.0 & 0x00800000 != 0
        }
        /// Sampled value of SVD field `RX_ASSOCIATED_AUXILIARY_24`.
        #[inline]
        pub const fn rx_associated_auxiliary_24(&self) -> bool {
            self.0 & 0x01000000 != 0
        }
        /// Sampled value of SVD field `BITS_25_26_OPAQUE`.
        #[inline]
        pub const fn bits_25_26_opaque(&self) -> u8 {
            (self.0 >> 25 & 0x3) as u8
        }
        /// Sampled value of SVD field `BIT_27_OPAQUE`.
        #[inline]
        pub const fn bit_27_opaque(&self) -> bool {
            self.0 & 0x08000000 != 0
        }
        /// Sampled value of SVD field `BIT_28_OPAQUE`.
        #[inline]
        pub const fn bit_28_opaque(&self) -> bool {
            self.0 & 0x10000000 != 0
        }
        /// Sampled value of SVD field `BITS_29_31_OPAQUE`.
        #[inline]
        pub const fn bits_29_31_opaque(&self) -> u8 {
            (self.0 >> 29 & 0x7) as u8
        }
    }
    /// Sample the complete masked event image.
    #[inline]
    pub fn sample_mac_interrupt(registers: &crate::WifiMacInterrupt) -> MacInterruptSnapshot {
        MacInterruptSnapshot(registers.status().read().bits())
    }
    /// Acknowledge exactly the event image returned by the paired sample.
    #[inline]
    pub fn acknowledge_mac_interrupt(
        registers: &crate::WifiMacInterrupt,
        snapshot: MacInterruptSnapshot,
    ) {
        // SAFETY: the opaque value can only be constructed by the paired
        // STATUS read and CLEAR is an SVD-validated full-width
        // write-one-to-clear register.
        unsafe {
            registers
                .clear()
                .write_with_zero(|writer| writer.bits(snapshot.0));
        }
    }
    /// An event image of the vendor comparison's choosing, for a probe
    /// image that replays a vendor acknowledgement.
    #[cfg(oer_probe)]
    #[doc(hidden)]
    pub const fn mac_interrupt_for_probe(bits: u32) -> MacInterruptSnapshot {
        MacInterruptSnapshot(bits)
    }

    /// Opaque event image sampled from `WIFI_MAC_POWER_INTERRUPT`.`STATUS`.
    #[must_use = "an interrupt snapshot must be inspected and acknowledged"]
    #[derive(Debug)]
    pub struct MacPowerInterruptSnapshot(u32);
    impl MacPowerInterruptSnapshot {
        /// Complete masked event image observed by the status read.
        #[inline]
        pub const fn bits(&self) -> u32 {
            self.0
        }
        /// Whether the sampled register contained no asserted event.
        #[inline]
        pub const fn is_empty(&self) -> bool {
            self.0 == 0
        }
        /// Sampled value of SVD field `TBTT_3`.
        #[inline]
        pub const fn tbtt_3(&self) -> bool {
            self.0 & 0x00000001 != 0
        }
        /// Sampled value of SVD field `TBTT_2`.
        #[inline]
        pub const fn tbtt_2(&self) -> bool {
            self.0 & 0x00000002 != 0
        }
        /// Sampled value of SVD field `TBTT_1`.
        #[inline]
        pub const fn tbtt_1(&self) -> bool {
            self.0 & 0x00000004 != 0
        }
        /// Sampled value of SVD field `TBTT_0`.
        #[inline]
        pub const fn tbtt_0(&self) -> bool {
            self.0 & 0x00000008 != 0
        }
        /// Sampled value of SVD field `TSF_TIMER_3`.
        #[inline]
        pub const fn tsf_timer_3(&self) -> bool {
            self.0 & 0x00000010 != 0
        }
        /// Sampled value of SVD field `TSF_TIMER_2`.
        #[inline]
        pub const fn tsf_timer_2(&self) -> bool {
            self.0 & 0x00000020 != 0
        }
        /// Sampled value of SVD field `TSF_TIMER_1`.
        #[inline]
        pub const fn tsf_timer_1(&self) -> bool {
            self.0 & 0x00000040 != 0
        }
        /// Sampled value of SVD field `TSF_TIMER_0`.
        #[inline]
        pub const fn tsf_timer_0(&self) -> bool {
            self.0 & 0x00000080 != 0
        }
        /// Sampled value of SVD field `BITS_8_31_OPAQUE`.
        #[inline]
        pub const fn bits_8_31_opaque(&self) -> u32 {
            self.0 >> 8 & 0xffffff
        }
    }
    /// Sample the complete masked event image.
    #[inline]
    pub fn sample_mac_power_interrupt(
        registers: &crate::WifiMacPowerInterrupt,
    ) -> MacPowerInterruptSnapshot {
        MacPowerInterruptSnapshot(registers.status().read().bits())
    }
    /// Acknowledge exactly the event image returned by the paired sample.
    #[inline]
    pub fn acknowledge_mac_power_interrupt(
        registers: &crate::WifiMacPowerInterrupt,
        snapshot: MacPowerInterruptSnapshot,
    ) {
        // SAFETY: the opaque value can only be constructed by the paired
        // STATUS read and CLEAR is an SVD-validated full-width
        // write-one-to-clear register.
        unsafe {
            registers
                .clear()
                .write_with_zero(|writer| writer.bits(snapshot.0));
        }
    }
    /// An event image of the vendor comparison's choosing, for a probe
    /// image that replays a vendor acknowledgement.
    #[cfg(oer_probe)]
    #[doc(hidden)]
    pub const fn mac_power_interrupt_for_probe(bits: u32) -> MacPowerInterruptSnapshot {
        MacPowerInterruptSnapshot(bits)
    }
}

